import{memorials,memorialTabs}from"./data.js";import{TabNav}from"./components/TabNav.js";import{MemorialCard}from"./components/MemorialCard.js";import{MemorialDetail}from"./components/MemorialDetail.js";import{LocationMap}from"./components/LocationMap.js";import{FactsPanel}from"./components/FactsPanel.js";document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("memorials-app");let a="overview",i=memorials[0];function o(){return`<div class="memorials-grid">${memorials.map(e=>MemorialCard(e,e.id===i.id)).join("")}</div>`}function r(){switch(a){case"overview":default:return o();case"history":return`<div class="memorials-history">${MemorialDetail(i)}</div>`;case"locations":return LocationMap(memorials);case"facts":return`<div class="facts-grid">${memorials.map(e=>FactsPanel(e)).join("")}</div>`}}function t(){e.innerHTML=`\n      <div class="memorials-page">\n        <div class="page-header">\n          <h1>Indian National Memorials</h1>\n          <p>Explore the sacred memorials that preserve India's rich heritage of sacrifice, freedom, and national pride</p>\n        </div>\n        ${TabNav(memorialTabs,a)}\n        <div class="memorials-content" id="memorials-content">\n          ${r()}\n        </div>\n      </div>`,document.querySelectorAll(".memorials-tab-btn").forEach(e=>{e.addEventListener("click",()=>{a=e.dataset.tab,t()})}),document.querySelectorAll(".memorial-card-btn, .memorial-card").forEach(e=>{e.addEventListener("click",o=>{const r=e.dataset.id||o.currentTarget.dataset?.id;r&&(i=memorials.find(e=>e.id===r)||i,a="history",t())})}),document.querySelectorAll(".legend-item").forEach(e=>{e.addEventListener("click",()=>{const o=e.dataset.id;o&&(i=memorials.find(e=>e.id===o)||i,a="history",t())})})}t()});